<template>
  <span class="orderByParentSpan arrow-color">
    <span
      class="up-arrow orderBy absolute cursor-pointer"
      :class="is_order_by_selected('asc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="asc"
      @click="OrderBy('asc')"
    ></span>
    <span
      class="down-arrow orderBy absolute cursor-pointer"
      :class="is_order_by_selected('desc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="desc"
      @click="OrderBy('desc')"
    ></span>
  </span>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useMasterDataLookupStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { saveSortOrderToStorage } from 'src/utils/ms_utlis';

export default defineComponent({
  mixins: [],
  props: {
    column_name: {
      type: String,
      required: true,
    },
    type_name: {
      type: String,
      required: true,
    },
  },
  components: {},

  computed: {
    // Guarded access: renders before MasterDataTypeList.mounted() writes
    // sortby_data_types[type_name] when the render gate is satisfied early by
    // the shared costing-element cache — the raw deref threw and blanked the
    // Master Data panel (DOCB-7039). Same guard the supplier fork ships.
    orderByMap(): Map<string, string> {
      return this.sortby_data_types[this.type_name]?.orderByMap ?? new Map();
    },
  },
  methods: {
    is_order_by_selected(direction: string) {
      return Boolean(
        this.orderByMap.has(this.column_name) &&
          this.orderByMap.get(this.column_name) == direction,
      );
    },

    // Lazy-init the store entry so a click before mounted() wrote it still
    // persists (mutating the computed's detached fallback Map would be lost).
    ensureOrderByMap(): Map<string, string> {
      if (!this.sortby_data_types[this.type_name]?.orderByMap) {
        this.sortby_data_types[this.type_name] = { orderByMap: new Map() };
      }
      return this.sortby_data_types[this.type_name].orderByMap;
    },

    OrderBy(direction: string) {
      const orderByMap = this.ensureOrderByMap();
      if (
        orderByMap.has(this.column_name) &&
        orderByMap.get(this.column_name) == direction
      ) {
        orderByMap.delete(this.column_name);
      } else {
        orderByMap.set(this.column_name, direction);
      }

      saveSortOrderToStorage(this.type_name, orderByMap);
      this.triggerApplyFilters();
    },

    triggerApplyFilters() {
      const event = new CustomEvent('ms_search', {
        detail: { data_type: this.type_name },
      });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { sortby_data_types } = storeToRefs(master_data_lookup_store);
    return {
      sortby_data_types,
    };
  },
});
</script>
