<template>
  <div class="row">
    <span v-if="orderByMap.size > 0">{{ $t('sort_by') }}</span>
    <template v-for="[key, value] in orderByMap" :key="key">
      <q-badge rounded color="primary" dense class="q-ml-md capitalize">
        {{ key }} : {{ value }}
        <q-icon
          name="close"
          class="q-ml-xs cursor-pointer"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useMasterDataLookupStore } from 'src/store/main';
import {
  removeSortOrderFromStorage,
  saveSortOrderToStorage,
} from 'src/utils/ms_utlis';

export default defineComponent({
  props: {
    type_name: {
      type: String,
      required: true,
    },
  },
  computed: {
    // Guarded access: this component renders BEFORE MasterDataTypeList's
    // mounted() writes sortby_data_types[type_name]. The render gate on
    // data[type_name].data can be satisfied early by the costing-element
    // cache (loaded from document/PO screens into the same store map), in
    // which case the raw `sortby_data_types[type_name]['orderByMap']` deref
    // threw a TypeError and blanked the whole Master Data panel (DOCB-7039).
    // Mirrors the guard the supplier fork already ships.
    orderByMap(): Map<string, string> {
      return this.sortby_data_types[this.type_name]?.orderByMap ?? new Map();
    },
  },
  methods: {
    removeFilter(key: string) {
      this.orderByMap.delete(key);

      if (this.orderByMap.size > 0) {
        saveSortOrderToStorage(this.type_name, this.orderByMap);
      } else {
        removeSortOrderFromStorage(this.type_name);
      }
      this.triggerApplyFilters();
    },
    triggerApplyFilters() {
      const event = new CustomEvent('ms_search', {
        detail: { data_type: this.type_name },
      });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { sortby_data_types } = storeToRefs(master_data_lookup_store);
    return {
      sortby_data_types,
    };
  },
});
</script>
