                <q-icon 
                  style="font-size: 18px" name="menu" @click.stop.prevent>
                  <q-menu transition-show="jump-down" transition-hide="jump-up" anchor="bottom middle" self="top middle">
                    <div style="padding: 10px">
                      <q-select
