                        v-if="!col.name.includes('_date')"
                      >
                      </q-input>
                      <q-input outlined dense v-model="filterValueByField[col.field]" data-cy="end_date" :clearable="true" style="width: 170px; height: 40px" v-if="col.name.includes('_date')">
                        <template v-slot:append>
                          <q-icon name="event" class="cursor-pointer" data-cy="btn_end_date">
                            <q-popup-proxy cover transition-show="scale" transition-hide="scale">
                              <q-date v-model="filterValueByField[col.field]" mask="YYYY-MM-DD">
                                <div class="row items-center justify-end">
                                  <q-btn v-close-popup label="Search" color="primary" flat @click="searchOneField"/>
                                </div>
                              </q-date>
                            </q-popup-proxy>
                          </q-icon>
                        </template>
                      </q-input>
                    </div>
                  </q-menu>
                </q-icon>
              </span>
              <!-- end -->
          </q-th>
        </q-tr>
      </template>
      <template v-slot:body="props">
        <q-tr
          :props="props"
          :id="props.key"
          :class="data[type_name].readonly ? '' : ''"
        >
          <template v-for="col in props.cols" :key="col.name" :props="props">
            <q-td v-if="col.name === 'action'">
              <div class="row float-right">
                <q-btn flat dense round @click.stop.prevent icon="more_horiz">
                  <q-menu
                    auto-close
                    transition-show="jump-down"
                    transition-hide="jump-up"
                    anchor="bottom middle"
                    self="top middle"
                  >
                    <q-list dense style="min-width: 100px">
                      <template v-if="parent != 'api_imported'">
                        <q-item clickable>
                          <q-item-section @click="editRow(props.rowIndex)">{{
                            $t('edit')
                          }}</q-item-section>
                        </q-item>
                        <q-separator inset />
                      </template>
                      <q-item clickable>
                        <q-item-section
                          @click="deleteClicked(props.rowIndex, props.row.id)"
                          ><span class="text-red">{{
                            $t('delete')
                          }}</span></q-item-section
                        >
                      </q-item>
                    </q-list>
                  </q-menu>
                </q-btn>
                <!-- <q-btn
                  class="float-right"
                  icon-right="delete"
                  no-caps
                  flat
                  dense
                  @click="deleteClicked(props.rowIndex, props.row.id)"
                >
                  <q-tooltip>{{ $t('delete') }}</q-tooltip>
                </q-btn>

                <q-btn
                  class="float-right"
