                  no-caps
                  flat
                  dense
                  @click="editRow(props.rowIndex)"
                >
                  <q-tooltip>{{ $t('edit') }}</q-tooltip>
                </q-btn> -->
              </div>
            </q-td>

            <q-td v-else>
              {{ formatDataInObject(props.row[col.name], col.name) }}
            </q-td>
          </template>
        </q-tr>
      </template>
    </q-table>
    <div class="back-white flex justify-end" v-if="total_pages > 1">
      <div class="row" style="margin-right: 0">
        <q-pagination
          v-model="current_page"
          color="primary"
          :max="total_pages"
          class="q-py-xs q-mx-md"
          :max-pages="6"
          input
          boundary-links
          @update:model-value="paginationItemClicked()"
        />
      </div>
    </div>

    <q-markup-table class="full-width" v-if="data[type_name].data.length == 0">
      <thead>
        <tr>
          <td class="text-center">
            {{ $t('no_data_found') }}
          </td>
        </tr>
      </thead>
    </q-markup-table>
  </template>

  <!-- pagination -->
  <!-- <div class="q-mt-md row full-width">
    <q-pagination
      v-if="total_pages > 1"
      v-model="current_page"
      :max="total_pages"
      :max-pages="6"
      direction-links
      unelevated
      color="black"
      active-color="black"
      class="doc2-pagination q-mb-md q-ml-auto q-mr-auto"
      @click="paginationItemClicked()"
    ></q-pagination>
  </div> -->

  <!-- create edit dialog -->
  <q-dialog
    v-model="show_edit_create"
    persistent
    @keydown.esc="show_edit_create = false"
    @hide="show_edit_create = false"
  >
    <EditCreate
      :type_name="type_name"
      :create_row="create_row"
      :model="selected_row"
      :selected_row_index="selected_row_index"
    />
  </q-dialog>

  <q-dialog
    v-model="display_table_alias_popup"
    @keydown.esc="display_table_alias_popup = false"
  >
    <TableAlias :alias_key_temp="type_name" />
  </q-dialog>

  <q-dialog v-model="show_upload_csv">
    <UploadCsv :type_name_key="type_name" />
  </q-dialog>

  <q-dialog v-model="showColumnDlg">
    <q-card>
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title><span class="text-weight-bold">{{$t('update_custom_column_label')}}</span></q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="height-75vh scrolle-y">
        <div class="row">
          <div class="col-6 q-pa-sm text-bold">
            {{ $t('name') }}
          </div>
          <div class="col-6 q-pa-sm text-bold">
            {{ $t('label') }}
          </div>

          <template v-for="(col, idx) in customColumList" :key="idx">
            <div class="col-6 q-pa-sm flex items-center">
              {{ col.name + ' (' + col.field + ')' }} 
            </div>
            <div class="col-6 q-pa-sm">
              <q-input outlined dense v-model="col.label" :label="$t('label')" />
