<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import ColumnOrderBy from './column-orderBy.vue';
import { masterDataApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import dragDropColumn from 'src/mixins/dragDropColumn';
import savedSortByBadges from './saved-sortby-badges.vue';
import { masterDataPrefix, masterDataLabelPrefix, CONSTANTS } from 'src/constants';
import { getSavedOrderByColumns, makeOrderByJsonForApi  } from 'src/utils/ms_utlis';
import EditCreate from 'src/pages/Settings/Components/MasterDataLookup/EditCreate.vue';
import TableAlias from 'src/pages/Settings/Components/MasterDataLookup/TableAlias.vue';
import UploadCsv from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/UploadCsv.vue';
import {
  useMasterDataLookupStore,
  useDocMasterDataLookUpStore,
  useSettingStore,
  useColumnFilterStore,
} from 'src/store/main';
import ColumnFilterBadges from 'src/pages/Dashboard/ColumnFilterBadges.vue';
import { fields } from 'src/formBuilder/components/GeneralSettings/fields-def';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, dragDropColumn, dateUtils],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: '',
    },
    parent: {
      type: String,
      default: '',
    },
  },
  components: {
    UploadCsv,
    EditCreate,
    TableAlias,
    ColumnOrderBy,
    savedSortByBadges,
    ColumnFilterBadges,
  },
  data() {
    return {
      actionButton: ref(false),
      selectedIndex: ref(0),
      show_upload_csv: ref(false),
      customColumnPreFix: 'custom_field_',
      enableSaveColumnOrderBtn: ref(false),
      searchOperatorByField: {} as { [key: string]: string },
      filterValueByField: ref({}) as dynamicObj,
      customColumList: ref([] as any),
      selected_columns: ref<string[]>([]),
      columnsFieldList: {} as any,
      isDateField: false,
      startDate: ref(''),
      endDate: ref(''),
      selectedDateField: ref(''),
      fieldsToExclude: ['action'],
    };
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const {
      deleteRow,
      getDataByType,
      getDataTypeFields,
      triggerCustomRecord,
      prepareColumns,
      checkEmptyColumns,
    } = master_data_lookup_store;
    const {
      data,
      columns,
      sortby_data_types,
      custom_records,
      columnListPreferenc,
    } = storeToRefs(master_data_lookup_store);

    // store to used for doc master data lookup UI
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { search_operators: search_operators_list, search_op_key_postfix, default_operator, date_search_operators } = storeToRefs(doc_ms_data_lookup_store);

    const settings_store = useSettingStore();
    const { getSetting, updateSetting } = settings_store;

    const columnFilterStore = useColumnFilterStore();
    columnFilterStore.$reset();
    const { quickFilterMap } = storeToRefs(columnFilterStore);

    return {
      updateSetting,
      custom_records,
      sortby_data_types,
      search_op_key_postfix,
      search_operators_list,
      triggerCustomRecord,
      getDataTypeFields,
      checkEmptyColumns,
      prepareColumns,
      getDataByType,
      getSetting,
      deleteRow,
      data,
      columns,
      loading: ref(false),
      filter_value: ref(''),
      edit_model: ref({} as any),
      create_row: ref(false),
      show_edit_create: ref(false),
      selected_row: ref({} as any),
      selected_row_index: ref(0),
      request_params: ref({} as any),
      current_page: ref(1),
      total_pages: ref(0),
      offset: ref(0),
      page_size: ref(15),
      total_records: ref(0),
      filter_data_json_str: ref(''),
      display_table_alias_popup: ref(false),
      search_operator: ref('contains'),
      default_operator,
      // search_operator_pref_key: ref(''),
      is_hidden: ref(false),
      showColumnDlg: ref(false),
      columnListPreferenc,
      quickFilterMap,
      date_search_operators
    };
  },
  computed: {
    selectStyle() {
      return {
        width: '100%',
        'max-height': this.selected_columns.length > 2 ? '40px' : 'auto',
        'overflow-y': this.selected_columns.length > 2 ? 'auto' : 'visible'
      }
    }
  },
  mounted: function () {
    this.initView();
    document.addEventListener(
      'init_view_' + this.type_name,
      this.initViewWrapper,
    );
    document.addEventListener('record_saved', this.recordSaved);
    document.addEventListener('alias_updated', this.aliasUpdated);
    document.addEventListener('ms_search', this.searchEvent);
    this.initailizeDragColumnsById(this.type_name);
    document.addEventListener(
      this.type_name + '-column-drop',
      this.onDropColumns,
    );
    this.quickFilterMap.set(this.type_name, {});
  },
  unmounted: function () {
    document.removeEventListener(
      'init_view_' + this.type_name,
      this.initViewWrapper,
    );
    document.removeEventListener('record_saved', this.recordSaved);
    document.removeEventListener('alias_updated', this.aliasUpdated);
    document.removeEventListener('ms_search', this.searchEvent);
    document.removeEventListener(
      this.type_name + '-column-drop',
      this.onDropColumns,
    );
  },

  methods: {
    initViewWrapper() {
      this.initView();
    },
    async initView() {
      try {
        this.loading = true;
        await this.getDataTypeFields(this.type_name);
        this.getOrderByColumns();
        await this.getDataServer();
        await this.prepareTableColumns();
        // this.setSearchOperator();
        console.log('columns after prepare', this.columns);
        this.columnsFieldList = Object.values(this.columns)
        .filter(col => !this.fieldsToExclude.includes((col as { name: string }).name))
        .map(col => ({
          label: (col as { label: string; name: string }).label,
          value: (col as { label: string; name: string }).name
        }));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    searchEvent(e: any) {
      if (e.detail.data_type != this.type_name) {
        return;
      }

      this.searchByAll();
    },

    // async setSearchOperator() {
    //   this.search_operator_pref_key = String(this.type_name + this.search_op_key_postfix).toUpperCase();
      
    //   this.search_operator = await this.getSetting(this.search_operator_pref_key);
     
    //   if (this.search_operator) {
    //     return;
    //   }

    //   this.search_operator = this.default_operator;
    // },

    //   if (this.search_operator) {
    //     return;
    //   }

    //   this.search_operator = this.default_operator;
    // },

    async getDataServer() {
      try {
        this.loading = true;
        this.request_params = {} as dynamicObj;
        this.request_params['skip'] = this.offset;
        this.request_params['limit'] = this.page_size;
        this.request_params['data_type'] = this.type_name;
        this.request_params['match_all'] = false;
        this.request_params['is_masterdata'] = true;
        this.makeOrderByForCall();
        await this.getDataByType(
          this.request_params,
          this.filter_data_json_str,
        );
        if (this.data[this.type_name].data.length > 0) {
          this.total_records = this.data[this.type_name].total_records;
          this.setTotalPages();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    makeOrderByForCall() {
      const order_by = makeOrderByJsonForApi(
        this.sortby_data_types[this.type_name]['orderByMap'],
      );
      if (!order_by || order_by.length == 0) {
        return;
      }
      this.request_params['sort_order_json'] = JSON.stringify(order_by);
    },
    onDropColumns() {
      let columnList = [];
      for (let column of this.columns) {
        columnList.push(column.name);
      }

      this.saveSortColumns(columnList);
    },
    async saveSortColumns(columns: any) {
      try {
        this.loading = true;
        let keyName = masterDataPrefix + this.type_name.toUpperCase();
        await this.updateSetting(keyName, JSON.stringify(columns));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.searchByAll();
      }
    },

    callSearchAll() {
      this.searchByAll();
    },
    onKeyupByOne(event: any) {
      if (event.key == 'Enter') {
        this.searchOneField();
      }
    },
    getSearchJsonByOne() {
      let filter_data_json_str = '';
      let filter_data_json = {} as dynamicObj;
      let filters = [] as dynamicObj[];

      const field = Object.keys(this.filterValueByField)[0];

      if (!field || field == '') {
        return filter_data_json_str;
      }

      Object.keys(this.filterValueByField).forEach((field) => {
        const filterValue = this.filterValueByField[field];
        const operatorValue = this.searchOperatorByField[field];

        if (filterValue && operatorValue) {
          filters.push({
            field: field,
            operator: operatorValue,
            value: filterValue,
          });

          //Add filters to create Badge
          const filterObj = this.quickFilterMap.get(this.type_name);
          filterObj[field] = filterValue;
          if (filterValue == '' || filterValue == undefined) {
            delete filterObj[field];
          }
          this.quickFilterMap.set(this.type_name, filterObj);
          // this.$emit('onUpdateValue', filterObj);
        } else {
          //Remove filters from Badge
          const event = new CustomEvent('remove_filter_key', { detail: field});
          document.dispatchEvent(event);
        }
      });

      if (filters.length > 0) {
        filter_data_json['filters'] = filters;
        filter_data_json['match_all'] = true;
        filter_data_json_str = JSON.stringify(filter_data_json);
      }

      return filter_data_json_str;
    },
    async searchOneField() {
      try {
        this.loading = true;
        this.resetPagination();

        this.filter_data_json_str = this.getSearchJsonByOne();
        await this.getDataServer();
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    // async operatorUpdatedOneField(value: string, field: string) {
    //   try {
    //     if (!value) {
    //       return;
    //     }
    //     this.showLoading();
    //     await this.updateSetting(`${this.search_operator_pref_key}_${field}`, value);
    //     notify.success(this.$t('MSG_SAVE'));
    //   } catch (err: any) {
    //     const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    //     notify.error(msg);
    //     logError(err);
    //   } finally {
    //     this.hideLoading();
    //   }
    // },

    async searchByAll() {
    try {
      if (this.filter_value && this.selected_columns.length == 0) {
        notify.error(this.$t('need_one_or_more_field'))
        return;
      }
      this.loading = true;

      const fields = this.data[this.type_name]['fields'];
      this.data[this.type_name] = {} as dynamicObj;
      this.data[this.type_name]['fields'] = fields;

      this.resetPagination();

      this.filter_data_json_str = this.getSearchJson();
      await this.getDataServer();
    } catch (error) {
      logError(error);
    } finally {
      this.loading = false;
    }
  },

  getSearchJson() {
    let filter_data_json_str = '';
    if ((!this.filter_value || this.filter_value == '') && !this.isDateField) {
      return filter_data_json_str;
    }
    const exclude_columns = [
      'action'
    ];

    let filter_data_json = {} as dynamicObj;
    let filters = [] as dynamicObj[];

    if (this.isDateField) {
      // Add date range filter
      if (this.startDate) {
        filters.push({
          field: this.selectedDateField,
          operator: 'after',
          value: this.startDate,
        });
      }
      if (this.endDate) {
        filters.push({
          field: this.selectedDateField,
          operator: 'before',
          value: this.endDate,
        });
      }
      if (filters.length > 0) {
        filter_data_json['match_all'] = true;
      }
    } else {
      Array.from(this.selected_columns).forEach((column: any) => {
        filters.push({
          field: column,
          operator: this.search_operator,
          value: this.filter_value.trim(),
        });
      });
      if (filters.length > 0) {
        filter_data_json['match_all'] = false;
      }
    }
    if (filters.length > 0) {
      filter_data_json['filters'] = filters;
      filter_data_json_str = JSON.stringify(filter_data_json);
    }

    return filter_data_json_str;
  },

    async paginationItemClicked() {
      try {
        this.calculateOffset();
        await this.getDataServer();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    editRow(index: number) {
      this.create_row = false;
      const row = JSON.parse(
        JSON.stringify(this.data[this.type_name].data[index]),
      );
      this.selected_row = row;
      this.selected_row_index = index;
      this.show_edit_create = true;
    },

    createRow() {
      this.create_row = true;
      if (this.columns.length <= 2) {
        notify.error(
          'No Columns found Please upload a csv before adding a new row',
        );
        return;
      }
      this.selected_row = {};
      this.selected_row_index = 0;
      this.show_edit_create = true;
    },

    async deleteClicked(index: number, id: string) {
      try {
        this.loading = true;
        const response = await this.deleteRow(this.type_name, id, index);
        if (!response || response.success !== true) {
          throw response;
        }

        notify.success('Record Deleted');
        this.handleCurrentPage();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    handleCurrentPage() {
      if (this.data[this.type_name].data.length != 0) {
        return;
      }
      this.paginationItemClicked();
    },

    recordSaved() {
      this.show_edit_create = false;
    },

    resetPagination() {
      this.offset = 0;
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    // setCurrentPage () {
    //   if (this.current_page > this.total_pages) {
    //     this.current_page--;
    //     this.setCurrentPage();
    //   }
    //   return this.current_page;
    // },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },
    itemDraggedComplete(e: any) {
      if (e.moved) {
        this.enableSaveColumnOrderBtn = true;
      }
    },

    async downloadAsCSV() {
      try {
        this.loading = true;
        const response = await masterDataApiService.downloadAsCSV(
          this.type_name,
        );
        if (response.error) {
          throw response.error;
        }

        const fileURL = window.URL.createObjectURL(new Blob([response]));
        const fileLink = document.createElement('a');
        fileLink.href = fileURL;
        fileLink.setAttribute('download', this.type_name + '.csv');
        document.body.appendChild(fileLink);
        fileLink.click();
        fileLink.remove();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    aliasUpdated() {
      this.display_table_alias_popup = false;
    },

    // async operatorUpdated(value: string) {
    //   try {
    //     if (!value) {
    //     return;
    //   }

    //   this.showLoading();
    //   await this.updateSetting(this.search_operator_pref_key, value);
    //   notify.success(this.$t('MSG_SAVE'));
    //   } catch (err: any) {
    //     const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
    //     notify.error(msg);
    //     logError(err);
    //   } finally {
    //     this.hideLoading();
    //   }
    // },

    getOrderByColumns() {
      this.sortby_data_types[this.type_name] = {};
      this.sortby_data_types[this.type_name]['orderByMap'] =
        getSavedOrderByColumns(this.type_name);
    },

    async hideShowColumns() {
      this.is_hidden = !this.is_hidden;

      if (this.is_hidden) {
        const emptyColumns = this.checkEmptyColumns(this.type_name).map(
          (col: any) => col.name as string,
        );
        this.columns = this.columns.filter(
          (col: any) => !emptyColumns.includes(col.name),
        );
        const isReadOnly = this.data[this.type_name].readonly;
        if (!isReadOnly) {
          this.columns.push({
            name: 'action',
            label: i18n.t('action'),
            field: 'action',
            align: 'right',
          });
        }
      } else {
        await this.prepareTableColumns();
      }
    },
    async refreshRecord() {
      try {
        this.loading = true;
        const item = this.custom_records.find(
          (item: any) => item.data_key === this.type_name,
        );
        await this.triggerCustomRecord(item.id);
        notify.success(
          this.$t('triggered_successfully'),
        );
      } catch (e: any) {
        const message = ApiExceptions.getErrorMessage(e);
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    formatDataInObject(value: any, colName: string): any {
      // Check for ISO date format
      if (typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(value)) {
        return this.formatDateAccordingToPreference(value);
      }
      return value;
    },
    async removeFilterBadge(filterObj: any) {
      //Remove from filter object
      this.filterValueByField = Object.fromEntries(
        Object.entries(this.filterValueByField).filter(
          ([k, v]) => filterObj[k] === v,
        ),
      );

      //Remove from filter json
      if (this.filter_data_json_str) {
        try {
          const jsonSearchString = JSON.parse(this.filter_data_json_str);
          const fileredParams = jsonSearchString.filters.filter(
            (f: { field: string; value: any }) => filterObj[f.field] === f.value,
          );
          jsonSearchString.filters = fileredParams;
          if (fileredParams.length > 0) {
            this.filter_data_json_str = JSON.stringify(jsonSearchString);
          } else {
            this.filter_data_json_str = '';
          }
        } catch {
          this.filter_data_json_str = '';
        }
      }
      await this.getDataServer();
    },
    async updateColumLabels() {
      this.showColumnDlg = false;
      const updatedLabels = this.customColumList.map((col: any) => ({ field: col.field, label: col.label }));
      await this.updateSetting(masterDataLabelPrefix + this.type_name.toUpperCase(), JSON.stringify(updatedLabels));
      await this.prepareTableColumns();
    },
    prepareCustomColumnList() {
      this.customColumList = this.columns
         
        .filter((col: any) => col.name && col.name.startsWith(this.customColumnPreFix))
        .map((col: any) => ({ field: col.field, name: col.label, label: col.label }));
    },
    async prepareTableColumns() {
      this.columns = [];
      await this.prepareColumns(this.type_name, this.is_hidden);
      this.prepareCustomColumnList();
    },
    filterColumns(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.columnsFieldList = Object.values(this.columns)
          .filter(col => !this.fieldsToExclude.includes((col as { name: string }).name))
          .map(col => ({
              label: (col as { label: string; name: string }).label,
              value: (col as { label: string; name: string }).name
            }));
          });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.columnsFieldList = this.columns.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1
        );
      });
    },
    hasfieldSelected(columns: string[]) {
      const hasDate = columns.some(col => col.includes('_date'));
      const prev = this.selected_columns;

      if (columns.length > 0 && columns[0].includes('_date')) {
        this.isDateField = true;
        this.selectedDateField = columns[0];
        if (columns.length > 1) {
          this.selected_columns = [columns[0]];
          notify.error(this.$t('cannot_select_more'));
        }
      } else {
        this.isDateField = false;
        this.startDate = '';
        this.endDate = '';
        if (hasDate) {
          this.selected_columns = [columns[0]];
          notify.error(this.$t('cannot_select_date_with_other'));
        }
      }
      if (this.filter_data_json_str) {
        if (columns.length == 0) {
          this.filter_value = '';
          this.filter_data_json_str = '';
        } else if (this.filter_value) {
          this.filter_data_json_str = this.getSearchJson();
        }
        this.resetPagination();
        this.getDataServer();
      }
    }
  },
});
</script>

