<template>
  <q-card>
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title
        ><span class="text-weight-bold">{{
          $t('upload_csv')
        }}</span></q-toolbar-title
      >
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>

    <q-card-section>
      <q-linear-progress v-if="loading" indeterminate />
      <div class="row">
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-input
            outlined
            dense
            v-model="data_type"
            :label="$t('data_type')"
            :disable="type_name_key != null && type_name_key != ''"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-file outlined dense v-model="file" :label="$t('file')">
            <template v-slot:prepend>
              <q-icon name="cloud_upload" />
            </template>
          </q-file>
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-select
            dense
            emit-value
            map-options
            outlined
            v-model="delimiter"
            :options="delimiterList"
            :label="$t('delimiter')"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-select
            dense
            emit-value
            map-options
            outlined
            v-model="on_conflict"
            :options="onConflictOptions"
            :label="$t('on_conflict')"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-checkbox v-model="replace_all" :label="$t('replace_all')" />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pa-sm">
          <q-checkbox
            v-model="auto_generate_id"
            :label="$t('auto_generate_id')"
          />
        </div>
      </div>
      <div class="row">
        <div class="col-sm-12 col-md-12 col-lg-12 q-pa-sm">
          {{ masterDataApiService?.uploadState?.uploadProgress || '' }}
        </div>
      </div>
    </q-card-section>

    <q-card-actions align="right">
      <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
      <f-btn :label="$t('upload')" @click="uploadFile()" class="q-mr-sm" />
    </q-card-actions>
  </q-card>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { masterDataApiService } from 'src/services';
import { defineComponent, ref, reactive } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  mixins: [helperMixin],
  name: 'upload-csv',
  props: {
    type_name_key: {
      type: String,
      default: '',
    },
  },
  components: { Loader },
  data() {
    return {
      loading: ref(false),
      file: ref<File | null>(null),
      data_type: ref(this.type_name_key),
      delimiter: ref(';'),
      on_conflict: ref('REPLACE'),
      replace_all: ref(false),
      auto_generate_id: ref(false),
    };
  },
  mounted: function () {
    this.masterDataApiService.uploadState.uploadProgress = '';
  },
  methods: {
    async uploadFile() {
      if (!this.data_type) {
        notify.error(this.$t('data_type_mandatory'));
        return;
      }
      if (!this.file) {
        notify.error(this.$t('please_select_file'));
        return;
      }

      if (this.file.type !== 'text/csv') {
        notify.error(this.$t('invalid_csv_file'));
        return;
      }

      try {
        this.loading = true;
        let formData = new FormData();
        formData.append('file', this.file);
        formData.append('data_type', this.data_type);
        formData.append('delimiter', this.delimiter);
        formData.append('on_conflict', this.on_conflict);
        formData.append('replace_all', String(this.replace_all));
        formData.append('auto_generate_id', String(this.auto_generate_id));

        notify.success(this.$t('file_upload_in_progress'));
        // Pass formData to the import method
        await masterDataApiService.importMasterData2(formData);

        // if this field is emppty means user want to create a new type
        if (!this.type_name_key) {
          const event = new CustomEvent('fetch_data_set_types', {});
          document.dispatchEvent(event);
        } else {
          // update current selected tab data
          const event = new CustomEvent('init_view_' + this.type_name_key, {});
          document.dispatchEvent(event);
        }

        //const response = await masterDataApiService.importMasterData(formData);
        //if (!response.success) {
        //throw { message: response.message };
        //}
        notify.success(this.$t('file_upload_completed'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    // Ensure the service is reactive here
    const masterDataApiServiceReactive = reactive(masterDataApiService);

    return {
      delimiterList: ref([
        { label: ';', value: ';' },
        { label: ',', value: ',' },
      ]),
      onConflictOptions: ref([
        { label: 'REPLACE', value: 'REPLACE' },
        { label: 'IGNORE', value: 'IGNORE' },
      ]),
      masterDataApiService: masterDataApiServiceReactive, // Reactive instance
    };
  },
});
</script>

<style scoped>
.inner-loader {
  position: absolute;
  width: 12%;
}
</style>
