<template>
  <q-card style="min-width: 55vw">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title
        ><span class="text-weight-bold">{{
          $t('custom_master_data')
        }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section class="row">
      <f-btn
        class="float-right q-ml-auto q-mr-sm"
        icon="add"
        :to="'/settings/data-validation/create-preset'"
        :label="$t('create_template')"
      />
      <f-btn
        :label="$t('create_endpoint')"
        icon="add"
        to="/settings/data-validation/create"
      />
    </q-card-section>

    <q-card-section>
      <DocBitsTable
        :rows="custom_records"
        :columns="mdColumns"
        row-key="id"
        table-id="custom_master_data_list_table"
        :loading="loading"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        no-data-label="no_record_found"
        flat-style
        @row-action="handleRowAction"
      >
        <template #body-cell-data_key="{ row }">
          {{ row.data_key }}
        </template>
      </DocBitsTable>
    </q-card-section>
  </q-card>
</template>

<script>
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions';
import helperMixin from 'src/mixins/helperMixin';
import { useMasterDataLookupStore, useUserStore } from 'src/store/main';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';

export default {
  mixins: [helperMixin],
  name: 'MasterDataListPopUp',
  components: { DocBitsTable },
  data() {
    return {
      mdColumns: [
        { name: 'data_key', label: this.$t('name'), field: 'data_key', align: 'left' },
        { name: 'method', label: this.$t('doc_type_classification_method'), field: 'method', align: 'left' },
        { name: 'body_type', label: this.$t('body_type'), field: 'body_type', align: 'left' },
      ],
      rowActions: [
        { key: 'edit', label: 'edit', icon: 'edit' },
        { key: 'trigger', label: 'trigger_endpoint', icon: 'refresh' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
      ],
    };
  },
  methods: {
    handleRowAction(payload) {
      const row = payload.row;
      const index = this.custom_records.findIndex((r) => r.id === row.id);
      switch (payload.action) {
        case 'edit':
          this.editRecord(row);
          break;
        case 'trigger':
          this.triggerRecord(row);
          break;
        case 'delete':
          this.deleteRecord(row, index);
          break;
      }
    },
    editRecord(row) {
      this.$router.push('/settings/data-validation/create/' + row.id);
    },
    async deleteRecord(row, index) {
      await this.deleteCustomRecord(row.id, index).then(() => {
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      });
    },
    async triggerRecord(row) {
      try {
        await this.triggerCustomRecord(row.id);
        notify.success(
          this.$t('triggered_successfully'),
        );
      } catch (e) {
        const message = ApiExceptions.getErrorMessage(e);
        this.loading = false;
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const user_store = useUserStore();
    const { sub_org_id } = storeToRefs(user_store);

    const master_data_store = useMasterDataLookupStore();
    const { custom_records, endpoint_information, mode, loading } =
      storeToRefs(master_data_store);
    const { deleteCustomRecord, triggerCustomRecord } = master_data_store;
    return {
      mode,
      sub_org_id,
      endpoint_information,
      loading,

      triggerCustomRecord,
      deleteCustomRecord,
      custom_records,
    };
  },
};
</script>
