<template>
  <q-card style="width: 700px; max-width: 1060px; min-height: 260px">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title
        ><span class="text-weight-bold">
          {{ $t('update_alias') }}
        </span>
      </q-toolbar-title>

      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section>
      <div class="row">
        <div class="col-12">
          <q-input
            readonly
            outlined
            v-model="table_alias_key"
            filled
            :label="$t('select_table')"
          />
        </div>
      </div>

      <div class="row q-mt-md">
        <div class="col-12">
          <q-input
            outlined
            v-model="table_alias_value"
            filled
            :label="$t('alias')"
            maxlength="100"
            style="height: 60px"
          />
        </div>
      </div>
    </q-card-section>

    <q-card-actions align="right">
      <q-btn
        class="q-mr-sm highlighted-back"
        :label="$t('cancel')"
        v-close-popup
      />
      <q-btn
        class="q-mr-sm"
        type="submit"
        color="primary"
        :label="$t('save')"
        @click="set_alias"
      />
    </q-card-actions>
  </q-card>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { useMasterDataLookupStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {},
  data() {
    return {};
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { setAlias } = master_data_lookup_store;
    const { aliases } = storeToRefs(master_data_lookup_store);

    return {
      aliases,
      setAlias,
      loading: ref(false),
      table_alias_value: ref('') as any,
      table_alias_key: ref('') as any,
    };
  },
  props: {
    alias_key_temp: {
      type: String,
      default: '',
    },
  },
  mounted: function () {
    this.table_alias_key = this.alias_key_temp;
    this.populateAlias();
  },
  methods: {
    async set_alias() {
      try {
        if (!this.validate()) {
          return;
        }

        this.loading = true;
        if (this.table_alias_value.length == 0) {
          this.table_alias_value = this.table_alias_key;
        }

        await this.setAlias(this.table_alias_key, this.table_alias_value);
        notify.success('alias is Updated.');
        const event = new CustomEvent('alias_updated', {});
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validate() {
      if (this.table_alias_key === null) {
        notify.error('Please select a Table to create an alias for');
        return false;
      }

      if (this.table_alias_value === null) {
        notify.error('Please set an alias to create for the table');
        return false;
      }

      return true;
    },

    populateAlias() {
      if (this.table_alias_key === null) {
        return;
      }

      const value = this.aliases[this.table_alias_key];
      if (value === null) {
        return;
      }
      this.table_alias_value = value;
    },
  },
});
</script>
