<!--vbase-->
<template>
  <q-card class="create-edit-card">
    <form @submit.prevent.stop="submitFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span v-if="!create_row" class="text-weight-bold">
            {{$t('edit_row')}}
          </span>
          <span v-else class="text-weight-bold">{{
            $t('create_row')
          }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <!-- body  -->
      <q-card-section class="q-pt-none edit-card-body">
        <div class="row full-width">
          <div class="full-width">
            <template v-for="key in data[type_name].fields" :key="key.id">
              <div v-if="!exclue_fields.includes(key)">
                <q-input
                  outlined
                  dense
                  :readonly="key == 'id' && !create_row"
                  v-model="edit_model[key]"
                  :label="key.toUpperCase()"
                  class="q-my-md"
                >
                </q-input>
              </div>
            </template>
          </div>
        </div>
      </q-card-section>

      <!-- buttons  -->
      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>

    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { useMasterDataLookupStore } from 'src/store/main';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: '',
    },
    create_row: {
      type: Boolean,
      required: true,
    },
    model: {} as any,
    selected_row_index: {
      type: Number,
      default: 0,
    },
  },
  components: {},
  data() {
    return {};
  },
  setup() {
    const master_data_lookup_store = useMasterDataLookupStore();
    const { updateRow } = master_data_lookup_store;
    const { data, exclue_fields } = storeToRefs(master_data_lookup_store);

    return {
      exclue_fields,
      data,
      loading: ref(false),
      edit_model: ref({} as any),
      row_id: ref(''),
      updateRow,
    };
  },
  mounted: function () {
    this.initView();
  },

  methods: {
    initView() {
      this.edit_model = this.model;
      this.row_id = this.model.id;
    },

    async submitFrom() {
      try {
        this.loading = true;
        if (!this.validateNewRow()) {
          return;
        }

        const response = await this.updateRow(
          this.type_name,
          this.edit_model,
          this.create_row,
          this.selected_row_index,
        );

        if (!response || response.success !== true) {
          throw response;
        }
        this.create_row
          ? notify.success('Created Record')
          : notify.success('Updated Record');

        const event = new CustomEvent('record_saved', { detail: {} });
        document.dispatchEvent(event);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validateNewRow(): boolean | string {
      try {
        if (
          !this.edit_model.hasOwnProperty('id') ||
          this.edit_model.id.replace(/\s+/g, '') == ''
        ) {
          throw this.$t('required_id');
        }

        if (
          this.row_id != this.edit_model.id &&
          this.data[this.type_name].ids.includes(this.edit_model.id)
        ) {
          throw this.$t('not_unique_id');
        }

        return true;
      } catch (err: any) {
        if (typeof err == 'string') {
          notify.error(err);
          return false;
        }
        throw err;
      }
    },
  },
});
</script>

